{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.NumberInputSchema",
  "description": "Schema for a floating-point number input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the number.",
      "type": [
        "string",
        "null"
      ]
    },
    "minimum": {
      "description": "Minimum allowed value (inclusive).",
      "type": [
        "number",
        "null"
      ],
      "format": "double"
    },
    "maximum": {
      "description": "Maximum allowed value (inclusive).",
      "type": [
        "number",
        "null"
      ],
      "format": "double"
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.VideoInputSchema",
  "description": "Schema for a video input (URL or base64-encoded).",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected video.",
      "type": [
        "string",
        "null"
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.ObjectInputSchema",
  "description": "Schema for an object input with named properties.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the object.",
      "type": [
        "string",
        "null"
      ]
    },
    "properties": {
      "description": "Schema for each property in the object.",
      "type": "object",
      "additionalProperties": {
        "$ref": "functions.expression.InputSchema"
      }
    },
    "required": {
      "description": "List of property names that must be present.",
      "type": [
        "array",
        "null"
      ],
      "items": {
        "type": "string"
      }
    }
  },
  "required": [
    "properties"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.ImageUrl",
  "description": "An image URL for multimodal input.",
  "type": "object",
  "properties": {
    "url": {
      "description": "The URL of the image (can be a data URL or HTTP URL).",
      "type": "string"
    },
    "detail": {
      "description": "The detail level for image processing.",
      "anyOf": [
        {
          "$ref": "agent.completions.message.ImageUrlDetail"
        },
        {
          "type": "null"
        }
      ]
    }
  },
  "required": [
    "url"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.StringInputSchema",
  "description": "Schema for a string input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the string.",
      "type": [
        "string",
        "null"
      ]
    },
    "enum": {
      "description": "If provided, the string must be one of these values.",
      "type": [
        "array",
        "null"
      ],
      "items": {
        "type": "string"
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.ImageUrlDetail",
  "description": "Detail level for image processing.",
  "oneOf": [
    {
      "description": "Let the model decide the detail level.",
      "type": "string",
      "const": "auto"
    },
    {
      "description": "Low detail mode (faster, less tokens).",
      "type": "string",
      "const": "low"
    },
    {
      "description": "High detail mode (more accurate, more tokens).",
      "type": "string",
      "const": "high"
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.File",
  "description": "A file attachment for multimodal input.",
  "type": "object",
  "properties": {
    "file_data": {
      "description": "Base64-encoded file data.",
      "type": [
        "string",
        "null"
      ]
    },
    "file_id": {
      "description": "The ID of a previously uploaded file.",
      "type": [
        "string",
        "null"
      ]
    },
    "filename": {
      "description": "The filename for display purposes.",
      "type": [
        "string",
        "null"
      ]
    },
    "file_url": {
      "description": "A URL to fetch the file from.",
      "type": [
        "string",
        "null"
      ]
    }
  }
}
